INSERT OR REPLACE INTO products VALUES('craft-set-3','Craft Scissors 3-Piece Set',26.99,'Three sizes (5", 7", 8.5") for paper, vinyl and mixed-media craft. Titanium-coated blades resist adhesive buildup.','[]','[{"name": "Pastel Mix", "hex": "#d8b4c8"}, {"name": "Bold Mix", "hex": "#4a6fa5"}]',6,'');
